.details p {
  margin-bottom: 0.75rem;
}

.details p:last-child {
  margin-bottom: 0;
}

footer {
  text-align: center;
  margin-top: 3rem;
  padding-top: 2rem;
  border-top: 2px solid var(--border);
  color: var(--text-secondary);
  font-size: 0.9rem;
